UPDATE lessons SET title='Year 3, Week 23, Lesson 4: Fluency: perimeter practice', data=json_patch(data,'{"child_mission":"Perimeter fluency adds side lengths accurately and includes units in every answer.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same method to a larger number or a new context, then compare two solution paths for accuracy.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nFind P: square 11 cm; rectangle 15 cm by 4 cm; triangle 8+9+10.\n\nFEEDBACK\n44 cm; 38 cm; 27 cm.\n\nWATCH FOR\nOmitting units or skipping a side produces incomplete perimeters.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nComplete a sixteen-item perimeter fluency set. Circle any item where you used a rectangle shortcut and show why it matches side addition.\n\nWrite a short reflection naming one step you corrected and why.","interactive_activities":null,"learning_area":"Mathematics","learning_intention":"Perimeter fluency adds side lengths accurately and includes units in every answer.","lesson_number":4,"lesson_role":"Fluency and review","materials":["Paper or typed answer space","Pencil","Optional: place-value chart or number line"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["MA2-GM-01"],"parent_notes":"Parent: Marking guidance for the independent task: Complete a sixteen-item perimeter fluency set. Circle any item where you used a rectangle shortcut and show why it matches side addition. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Original demonstration: Set: square 7 cm; rectangle 9 cm×6 cm; irregular 3+5+4+6 cm.\n\nParent: Written model 2: Common error: Omitting units or skipping a side produces incomplete perimeters. Correction: 44 cm; 38 cm; 27 cm.\n\nParent: Likely misconception: Omitting units or skipping a side produces incomplete perimeters. Keep sample answers out of the child role.","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":0,"explanation":"Perimeter fluency adds side lengths accurately and includes units in every answer. The other choices avoid explaining the actual strategy.","options":["Perimeter fluency adds side lengths accurately and includes units in every answer.","Omitting units or skipping a side produces incomplete perimeters.","Ignore place value and read digits from left to right as ones only.","Copy the model numbers and call that independent work."],"question":"Which idea is taught in the stage \"Understand and model\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"Make the method visible: name the values, places or steps you used and say why that step is valid. The other choices avoid explaining the actual strategy.","options":["Make the method visible: name the values, places or steps you used and say why that step is valid.","Writing only the final answer without working does not show the method.","Copy the model numbers and call that independent work.","Treat a missing zero as if it does not change the value."],"question":"Which idea is taught in the stage \"Show the working\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"Use an intentionally incorrect attempt as a comparison. Name its specific mathematical error, then show the corrected working. The other choices avoid explaining the actual strategy.","options":["Use an intentionally incorrect attempt as a comparison. Name its specific mathematical error, then show the corrected working.","Changing the answer without repairing the method does not fix the error. Omitting units or skipping a side produces incomplete perimete